def load(path):
    t = open(path, encoding="utf-8").read()
    m = re.match(r"^---\n(.*?)\n---\n", t, re.S)
    fm, body = (m.group(1), t[m.end():]) if m else ("", t)
    # 2026-09-13: \s* 가 줄바꿈까지 먹어 빈 값(published:) 다음 줄을 값으로 읽던 버그 → 공백·탭만 허용
    g = lambda k, d="": (re.search(rf"^{k}:[ \t]*\"?(.*?)\"?[ \t]*$", fm, re.M) or [None, d])[1]
    return dict(path=path, name=os.path.basename(path)[:-3], fm=fm, body=body,
                title=g("title"), series=g("series"), category=g("category") or g("series"),
                episode=int(g("episode", "0") or 0), form=g("form"), unique=g("unique_asset"),
                description=g("description"), affiliate=g("affiliate"),
                # 2026-10-02: 번호·날짜 없는 제휴 원고는 '재고'다 — 매일 작업이 제휴 차례에 꺼내 번호와 예약일을 붙인다.
                # 발행 순서 밖이므로 날짜를 비워 순서 계산(V9·V11·직전 편·제휴 차례)에서 뺀다. created로 넣으면 순서 한가운데 끼어든다
                stock=bool(g("affiliate")) and not (g("published") or g("scheduled")), created=_datekey(g("created") or ""),
                date="" if (g("affiliate") and not (g("published") or g("scheduled"))) else _datekey(g("published") or g("scheduled") or g("created") or ""))

def _datekey(v):
    """'YYYY-MM-DD' 또는 'YYYY-MM-DD HH:MM'(뒤 주석 무시). 2026-09-17: 하루 두 슬롯(13:30·19:30)이라
    날짜만으로는 같은 날 두 편의 앞뒤가 갈리지 않아 시리즈 이름순으로 잘못 정렬됐다 → 시각까지 비교한다.
    날짜만 있는 값은 같은 날 시각 있는 값보다 앞으로 정렬된다."""
    m = re.match(r"\s*(\d{4}-\d{2}-\d{2}(?: \d{2}:\d{2})?)", v or "")
    if m: return m.group(1)
    parts = (v or "").split()   # 날짜가 아닌 값(예: '# 미정 …')은 예전과 같게 첫 토큰을 쓴다
    return parts[0] if parts else ""

def h2s(b): return re.findall(r"^## (.+)$", b, re.M)

def sect_type(h):
    h = re.sub(r"^\d+\.\s*", "", h)
    for k, rx in [("요약", r"30초 요약|요약"), ("FAQ", r"자주 묻는 질문|FAQ"), ("참고", r"참고 자료"),
                  ("프롬프트", r"프롬프트"), ("금지", r"하지 마|하지 말|금지"),
                  ("예시", r"예시|예문|문구|사례|실수|답글|이렇게|실제로|문장|갈립니다|갈리"),
                  ("절차", r"단계|순서|방법|하는 법|체크|확인|점검"),
                  ("비교", r"비교|차이|vs|VS|갈라|나뉩|구분|판정|종류"),
                  ("원리", r"왜|이유|원리|구조|기준|무엇|뭐|뜻|정확히|아니라")]:
        if re.search(rx, h): return k
    return "기타"

def signature(p): return tuple(sect_type(h) for h in h2s(p["body"]))

def title_mold(t):
    """네이버: 스킬 STEP 0-2의 제목 틀 5개 + '(N가지)' 꼬리. 티스토리: 부제(— 뒤) 틀.
    키워드 선행 제목은 쉼표 뒤 훅으로 다시 나눈다(2026-09-18, 아래 주석)."""
    if PLATFORM == "tistory":
        # 2026-09-27: 새 제목은 ': '로 가른다(티스토리가 —를 &mdash;로 저장해 RSS에 엔티티가 샌다). 옛 제목의 —도 계속 읽는다
        sep = next((x for x in ("—", ": ") if x in t), None)
        sub = t.split(sep, 1)[1].strip() if sep else ""
        if re.search(YEAR_TAIL_RX, t) and not sub.replace(re.search(YEAR_TAIL_RX, t).group(0), "").strip(): return "(연도) 꼬리만"
        if re.search(r"\d+\s*(가지|개|단계)", sub): return "숫자 부제"
        if re.search(r"(와|과|vs|VS|,)\s*.*(차이|다릅|갈리|고르는|비교)", sub): return "대조 부제"
        if re.search(r"(하면|안 되|막힙|과태료|손해|못 씁|안 통하|못 채우|이유)", sub): return "손실·이유 부제"
        if re.search(r"[?？]\s*$|(까|나요)\s*$", t): return "질문형"
        if re.search(r"(입니다|됩니다|없습니다|있습니다|먼저|부터)\s*(\(20\d\d\))?\s*$", t): return "결론 부제"
        return "기타"
    if re.search(TITLE_TAIL_RX, t): return "(N가지) 꼬리"
    if re.search(r"[?？]\s*$|(까|나요|을까요)\s*$", t): return "질문형"
    if re.search(r"^\d", t): return "숫자 선행"
    if re.search(r"(와|과|vs|VS) .*(다릅니다|갈립니다|아닙니다|안 되는|되는 곳|차이)", t): return "대조형"
    if "," not in t and re.search(r"(입니다|합니다|됩니다|받습니다|없습니다|있습니다)\s*$", t): return "한 문장 결론"
    # 2026-09-18: 메인 키워드는 제목 앞머리에 고정한다(블로그탭 1~3위 45%가 검색어 정확 일치, 첫 어절 위치 중앙 0.
    # 내 글도 제목 정확 일치 O면 10위 안 55%·X면 35%). 그래서 '키워드+훅'이 한 칸에 몰려 V3가 상시 경고가 됐다.
    # 앞머리 고정은 그대로 두고 **쉼표 뒤 훅의 성격**으로 회전을 본다 — 회전의 목적은 뼈대 다양화지 키워드 후퇴가 아니다.
    m = re.match(r"^[^,]{2,25},\s*(.+)$", t)
    if m:
        hook = m.group(1)
        # 순서 주의: 숫자를 먼저 보면 "안 하면 500만원입니다"(손실)·"1년 넘긴 알바도 대상입니다"(결론)가
        # 전부 숫자 훅으로 빨려 들어간다. 훅의 성격을 먼저 보고, 숫자는 **금액·비율이 결론인 때**만 잡는다.
        if re.search(r"[?？]\s*$|(까|나요|을까요)\s*$", hook): return "키워드+질문 훅"
        if re.search(r"(아니라|아닙니다|와 |과 |vs|VS|다릅니다|갈립니다|갈랐습니다|갈렸습니다|차이)", hook): return "키워드+대조 훅"
        if re.search(r"(막힙|안 되|안 됩|안 하면|안 쓰면|못 |놓치|과태료|벌금|가산세|손해|떠납|잃|위험|주의)", hook): return "키워드+손실 훅"
        if re.search(r"\d[\d,]*\s?(원|만원|억|%|배|시간|일|개월)", hook): return "키워드+숫자 훅"
        return "키워드+결론 훅"
    return "기타"

def closing_mold(b):
    """네이버: '**참고 자료**' 앞의 마지막 구분선 뒤. 티스토리: FAQ 직전 섹션의 성격."""
    if PLATFORM == "tistory":
        hs = [h for h in h2s(b) if not re.search(r"참고 자료", h)]
        idx = next((i for i, h in enumerate(hs) if re.search(r"자주 묻는 질문|FAQ", h)), None)
        prev = hs[idx - 1] if idx else (hs[-1] if hs else "")
        if re.search(r"점검표|체크 ?리스트|점검 ?목록|확인 ?목록", prev): return "점검표"   # 10-04: '점검에 쓰세요'(09편) 같은 소제목까지 잡던 오탐을 좁혔다
        if re.search(r"재현", prev): return "재현 방법"
        if re.search(r"계산표|내 숫자", prev): return "빈칸 계산표"
        if re.search(r"정답표|판정표", prev): return "정답표"
        if re.search(r"프롬프트", prev): return "프롬프트"
        if re.search(r"유형|처방|규칙", prev): return "규칙·유형"
        return "기타"
    idx = b.rfind("**참고 자료**")
    seg = b[:idx] if idx > 0 else b
    last = seg.rfind("\n---\n")
    if last > 0:
        seg2 = seg[:last]; prev = seg2.rfind("\n---\n")
        tail = seg2[prev:] if prev > 0 else seg2[-1500:]
    else:
        tail = seg[-1500:]
    if re.search(r"오늘 할 일은", tail): return "오늘 할 일"
    if re.search(r"\| 통설 \|", tail): return "정답표"
    if re.search(r"^\| .*\|$", tail, re.M): return "빈칸 계산표"
    if re.search(r"___|예 / 아니오", tail): return "빈칸 판정"
    if re.search(r"^\d\. .+다\.$", tail, re.M): return "규칙 재진술"
    if re.search(r"재현", tail): return "재현 방법"
    if re.search(r"\d+분", tail) and re.search(r"준비물|소요", tail): return "소요 시간"
    return "기타"

def faq_count(b):
    m = re.search(r"^## .*(자주 묻는 질문|FAQ)[^\n]*\n(.*?)(?=^## |\Z)", b, re.M | re.S)
    return len(re.findall(r"^### ", m.group(2), re.M)) if m else 0

def counts(p):
    b = p["body"]
    tables = len(re.findall(r"^\|---", b, re.M))
    imgs = len(re.findall(r"^\[이미지 \d", b, re.M)) if PLATFORM == "naver" else len(re.findall(r"!\[\[[^\]]+\.png\]\]", b))
    dont = re.search(r"^## .*(하지 마세요|하지 말)[^\n]*\n(.*?)(?=^## |^\*\*마무리|^\[이미지|\Z)", b, re.M | re.S)
    dn = len(re.findall(r"^\d+\. ", dont.group(2), re.M)) if dont else 0
    return (len(h2s(b)), tables, imgs, dn if PLATFORM == "naver" else faq_count(b))

def grams(b, n=6):
    b = re.sub(r"^(>|\||\[이미지|!\[\[|---|#).*$", "", b, flags=re.M)
    # 10-04: 인용 목록('- [출처](URL) — 설명')과 링크 주소는 뺀다. 같은 1차 출처를 인용하면 출처명·URL이 원본과 같은 게 정상이고,
    # 그 한 줄이 V10 겹침의 대부분이었다(36편: 겹친 6-gram 346 중 334가 법령정보 링크 한 줄). 중복 판정은 본문 문장으로 한다
    b = re.sub(r"^\s*[-*]\s*\[[^\]]*\]\(https?://[^)]*\).*$", "", b, flags=re.M)
    b = re.sub(r"\]\(https?://[^)]*\)", "]", b)
    b = re.sub(r"https?://\S+", "", b)
    b = re.sub(r"```.*?```", "", b, flags=re.S)
    b = re.sub(r"\s+", "", b)
    return set(b[i:i + n] for i in range(len(b) - n + 1))

def sentences(b, minlen=25):
    b = re.sub(r"^(>|\||\[이미지|!\[\[|---|#).*$", "", b, flags=re.M)
    # 굵게(**)·링크 주소를 벗기고 나눈다 — "…넓어집니다.** 다음 문장"은 마침표 뒤가 *라 안 나뉘어 같은 문장을 놓쳤다(2026-09-27 /20)
    b = re.sub(r"^\s*[-*]\s*\[[^\]]*\]\([^)]*\).*$", "", b, flags=re.M)   # 링크로 시작하는 참고 자료 줄(출처 제목)은 인용이라 뺀다
    b = re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", b).replace("**", "")   # 링크는 문구만 남긴다
    return {s.strip() for s in re.split(r"(?<=[.?!다요])\s+", b) if len(s.strip()) >= minlen}

def source_of(p):
    """티스토리 원고의 source: "[[NN편-…]]" → 원본 네이버 원고 경로 (없으면 None)."""
    m = re.search(r'^source:[ \t]*"?\[\[([^\]|#]+)', p["fm"], re.M)
    if not m: return None
    name = m.group(1).strip() + ".md"
    path = os.path.join(CORPORA["naver"], name)
    if os.path.exists(path): return path
    # 「AI 도구 비교」 원본은 하위 폴더에 있다 — 바로 아래만 보면 비교 시리즈 V10이 전부 건너뛰어졌다(2026-10-01)
    hits = glob.glob(os.path.join(CORPORA["naver"], "**", name), recursive=True)
    return hits[0] if hits else None

def intro_text(p):
    b = p["body"]
    if PLATFORM == "tistory":   # 발행정보 인용 블록 제외: H1 이후부터
        h1 = re.search(r"^# ", b, re.M); b = b[h1.start():] if h1 else b
    return re.sub(r"^# .*$|^> .*$|^\[이미지.*$|^!\[\[.*$|^---$", "", b, flags=re.M).strip()[:600 if PLATFORM == "tistory" else 400]

def ritual_hits(p):
    hits = []; R = rituals()
    body_scan = p["body"]
    if PLATFORM == "tistory":   # 발행정보 블록(발행 전 삭제됨)은 검사에서 뺀다
        h1 = re.search(r"^# ", body_scan, re.M); body_scan = body_scan[h1.start():] if h1 else body_scan
    for k, rx in R.items():
        if rx and re.search(rx, body_scan, re.M): hits.append(k)
    intro = intro_text(p)
    if re.search(OPENING_RX[PLATFORM], intro): hits.append("R8 '~있으실 겁니다/계실 겁니다' 도입" if PLATFORM == "naver" else "T2 도입 꼬리 '아래에서 ~'")
    if PLATFORM == "naver":
        if re.search(TITLE_TAIL_RX, p["title"]): hits.append("R10 '(N가지/단계/개)' 제목 꼬리")
    else:
        if re.search(YEAR_TAIL_RX, p["title"]): hits.append("T5 '(2026)' 연도 제목 꼬리")
        if re.search(r"\d+\s*(가지|개|단계)\s*(\(20\d\d\))?\s*$", p["title"]): hits.append("T10 '(N가지/단계/개)' 부제 꼬리")
        if faq_count(body_scan) == 5: hits.append("T6 FAQ 정확히 5문항")
        if closing_mold(body_scan) == "점검표": hits.append("T7 FAQ 직전 H2가 점검표/체크리스트")
        if "갈랐습니다" in p["description"]: hits.append("T8 description '~갈랐습니다'")
    return hits

def corpus(exclude=()):
    root = CORPORA[PLATFORM]
    fs = sorted(glob.glob(root + "/*.md")) + sorted(glob.glob(root + "/*/*.md"))
    return [load(f) for f in fs if os.path.abspath(f) not in exclude]

def _held(q):
    return bool(re.search(r"^status:[ \t]*\"?hold\b", q["fm"], re.M))

def recent_of(p, posts, n):
    """직전 편 두 계열: 같은 시리즈의 앞 n편, 전체 코퍼스의 앞 n편 — 둘 다 발행 순서(published/scheduled/created) 기준.
    2026-10-09 (Thomas 승인): 같은 시리즈 앞 편을 원고 번호(episode) 순이 아니라 날짜 순으로 고른다 — 번호는 식별자일 뿐이고,
    예약 재배열·hold로 번호와 실제 순서가 갈리면 번호 순은 거짓 FAIL을 냈다(티스토리 93→94). status: hold 원고는 발행 순서 밖이라
    다른 원고의 직전 편 후보에서 뺀다(제휴 재고와 같은 방식). 날짜 없는 원고(제휴 재고)는 순서 계산에서 빠진다.
    같은 날짜(시각까지 같거나 둘 다 날짜만)는 (날짜, episode, 파일 이름) 순으로 앞뒤를 정한다 — 같은 날 쓴 두 원고는 번호가 작은 쪽이 앞이다.
    이 글의 날짜가 없거나 날짜 형식이 아니면(예: scheduled 칸의 '# 미정 …' 메모) 실제 순서를 알 수 없으므로 같은 시리즈 앞 편은
    예전처럼 원고 번호로 고른다 — 비교가 사라져 검사가 느슨해지지 않게. 같은 이유로 날짜 형식이 아닌 글은 날짜 순 같은 시리즈 후보에서 빠진다.
    전체 계열은 예전대로 날짜가 이 글보다 앞선 글만 본다."""
    dated = lambda d: bool(re.match(r"\d{4}-\d{2}-\d{2}", d or ""))
    key = lambda q: (q["date"], q["episode"], q["name"])
    cand = [q for q in posts if q["date"] and q["name"] != p["name"] and not _held(q)]
    if dated(p["date"]):
        same = sorted((q for q in cand if q["series"] == p["series"] and dated(q["date"]) and key(q) < key(p)), key=key)[-n:]
    else:
        same = sorted((q for q in posts if q["series"] == p["series"] and 0 < q["episode"] < p["episode"] and not _held(q)),
                      key=lambda q: q["episode"])[-n:]
    bydate = sorted((q for q in cand if q["date"] < (p["date"] or "9999")),
                    key=lambda q: (q["date"], q["series"], q["episode"]))[-n:]
    seen, out = set(), []
    for q in same + bydate:
        if q["name"] not in seen: seen.add(q["name"]); out.append(q)
    prev, seen2 = [], set()
    for q in [same[-1] if same else None, bydate[-1] if bydate else None]:
        if q and q["name"] not in seen2: seen2.add(q["name"]); prev.append(q)
    return out, prev

def check(path, posts):
    p = load(path); fails = warns = 0
    def out(level, code, msg):
        nonlocal fails, warns
        print(f"  [{level}] {code} {msg}")
        if level == "FAIL": fails += 1
        else: warns += 1
    print(f"\n{p['name']}  ({PLATFORM} · {p['series']} {p['episode']}편)")
    hits = ritual_hits(p)
    lvl = "FAIL" if len(hits) >= THRESH["ritual_fail"] else ("WARN" if len(hits) >= THRESH["ritual_warn"] else None)
    if lvl: out(lvl, "V1", f"의례 문구 {len(hits)}개: " + " / ".join(h.split(' ',1)[0] for h in hits))
    for h in hits: print(f"         · {h}")
    sig = signature(p); rec, prev = recent_of(p, posts, THRESH["recent"])
    # 10-04: 회전 규칙(직전 편과 다른 뼈대·제목 틀·마무리·개수·유형)은 원고를 쓸 때 지키는 규칙이다. 이미 발행·예약된 글의 순서는
    # 바꿀 수 없어 경고가 할 일을 주지 못하고, 옛 글에 사실대로 form을 채우자 V9 연속 FAIL이 6편 새로 났다(F3 발행 제목과 같은 논리)
    st = re.search(r"^status:[ \t]*(\S+)", p["fm"], re.M)
    locked = bool(st) and st.group(1).strip('"') in ("published", "scheduled")
    if locked: print("  · 회전 검사(V2·V2c·V3·V3b·V4·V8·V9 연속)는 원고 단계 규칙 — 발행·예약 글은 건너뛴다")
    rot = (lambda *a, **k: None) if locked else out
    same_sig = [q["name"] for q in rec if signature(q) == sig]
    if same_sig: rot("FAIL", "V2", f"섹션 구조가 직전 편과 동일: {', '.join(same_sig)}  {'→'.join(sig)}")
    else:
        n_all = sum(1 for q in posts if signature(q) == sig)
        if n_all: rot("WARN", "V2", f"같은 섹션 구조가 코퍼스에 {n_all}편  {'→'.join(sig)}")
    if PLATFORM == "naver" and sig and sig[-2:] == ("프롬프트", "금지"): out("WARN", "V2b", "끝 두 섹션이 '프롬프트→금지목록' (시리즈 27/32편과 같은 결말)")
    if PLATFORM == "tistory" and sig[:1] == ("요약",): 
        n_sum = sum(1 for q in posts if signature(q)[:1] == ("요약",))
        if any(signature(q)[:1] == ("요약",) for q in prev): rot("WARN", "V2c", f"첫 섹션이 '요약'으로 시작 — 직전 편과 같음 (코퍼스 {n_sum}편). 요약 블록은 4형 회전")
    tm = title_mold(p["title"])
    same_tm = [q["name"] for q in prev if title_mold(q["title"]) == tm]
    if same_tm: rot("WARN", "V3", f"제목 틀 '{tm}' 이 직전 편과 같음: {', '.join(same_tm)}")
    bydate_recent = sorted((q for q in posts if q["date"] and q["date"] < (p["date"] or "9999")), key=lambda q: q["date"])[-2:]
    tailkey = "(N가지)" if PLATFORM == "naver" else "숫자 부제"
    if tailkey in tm and any(tailkey in title_mold(q["title"]) for q in bydate_recent): rot("WARN", "V3b", f"'{tailkey}' 꼬리 — 최근 3편 중 2편 이상 (3편 중 1편 이하)")
    cm = closing_mold(p["body"])
    same_cm = [q["name"] for q in prev if closing_mold(q["body"]) == cm]
    if same_cm: rot("WARN", "V4", f"마무리 틀 '{cm}' 이 직전 편과 같음: {', '.join(same_cm)}")
    g = grams(p["body"]); best = (0, None)
    for q in posts:
        j = len(g & grams(q["body"])) / max(1, len(g | grams(q["body"])))
        if j > best[0]: best = (j, q["name"])
    if best[0] >= THRESH["jaccard_warn"]: out("WARN", "V5", f"6-gram 유사도 {best[0]:.3f} vs {best[1]} (기준 {THRESH['jaccard_warn']})")
    # V14 (2026-10-07): 다른 글 2편 이상에 이미 있는 문장. 네이버 스팸 사례(224335446939)의 '동일·유사 템플릿, 문장 일부만 바꾼 페이지'.
    # 6-gram 평균은 낮아도(네이버 100편 0.007) 고정 문장이 14편·4편씩 되풀이됐다('이 시리즈는 특정 회사와 이해관계 없이…', '…가정한 사례입니다').
    # 쇼핑커넥트 고지 문구는 Thomas가 정한 그대로 써야 해서 뺀다
    mine = {s for s in sentences(p["body"]) if "쇼핑 커넥트 활동의 일환" not in s}
    if mine:
        seen = collections.Counter()
        for q in posts:
            for s in mine & sentences(q["body"]):
                seen[s] += 1
        rep = [s for s, c in seen.items() if c >= 2]
        if rep:
            out("WARN", "V14", f"다른 글 2편 이상에 이미 있는 문장 {len(rep)}개 — 같은 뜻도 이 글의 말로 새로 쓴다: '{rep[0][:50]}'")
    # V15 (2026-10-07): 이미 발행·예약된 글과 검색 의도가 겹치는지. 메인·틈새 키워드 낱말 2개 이상이 같으면 의심
    # (10-07 실측: 76편 '배민 리뷰 삭제' ↔ 12편 '배민 리뷰 게시중단'). 같은 의도면 새 글 대신 그 글의 보강·후속으로, 다르면 첫 문단에서 갈래를 밝히고 서로 링크한다
    kw_of = lambda q: [k.strip().lower() for k in re.sub(r"^\[|\]$", "", (re.search(r"^keywords:[ \t]*(.*)$", q["fm"], re.M) or [0, ""])[1].strip()).split(",") if k.strip()][:2]
    st_of = lambda q: (re.search(r"^status:[ \t]*(\S+)", q["fm"], re.M) or [0, ""])[1]
    mk = kw_of(p)
    if mk:
        hits = []
        for q in posts:
            if st_of(q) not in ("published", "scheduled"):
                continue
            for a_ in mk:
                for b_ in kw_of(q):
                    ta, tb = a_.split(), b_.split()
                    if a_ == b_ or (ta[0] == tb[0] and (set(ta[1:]) & set(tb[1:])) - V15_GENERIC):
                        hits.append(f"{q['name'][:24]}('{b_}')"); break
                else:
                    continue
                break
        if hits:
            out("WARN", "V15", f"발행된 글과 키워드가 겹친다 {len(hits)}편 — 같은 의도면 그 글의 보강·후속으로, 다르면 첫 문단에서 갈래를 밝히고 서로 링크: " + " / ".join(hits[:3]))
    # V16 (2026-10-07 Phase 3): 기존 글과 견준 판정 — CREATE_NEW(새 글) · UPDATE_EXISTING(기존 글 보강) · REJECT(쓸 필요 없음).
    # 정본은 blog_taxonomy.py decide: 주제 핵심·질문 갈래·도구·키워드·제목·본문 유사도를 따로 재고 규칙으로 정한다(유사도 하나로 자르지 않는다).
    # 원고 단계 경고다 — 판정과 근거를 보고 사람이 정하며, 이 검사는 어떤 글도 고치지 않는다
    if PLATFORM == "naver" and not locked:
        try:
            from . import taxonomy as bt
            dec = bt.decide_file(path)
        except Exception as e:
            dec = None
            print(f"  · V16 판정 생략 — {e}")
        if dec and dec["decision"] != "CREATE_NEW":
            out("WARN", "V16", f"{dec['decision']} → {dec['matched_article']['id']}: {dec['reason']}")
        elif dec and dec["related"]:
            print("  · V16 CREATE_NEW — 가까운 글(서로 링크 후보): " + ", ".join(r["id"][:22] for r in dec["related"][:3]))
    if not p["unique"]: out("WARN", "V6", "프론트매터 unique_asset 없음 — 이 글에만 있는 것(실측·계산 예제·화면 절차·1차 출처 원문·사례) 1개를 선언할 것")
    prm_rx = RITUALS_NAVER["R4 '너는 ~하는 사람이야' 프롬프트"] if PLATFORM == "naver" else RITUALS_TISTORY["T9 '너는 ~야' 역할형 프롬프트 코드블록"]
    if "실무" in p["category"] and re.search(prm_rx, p["body"], re.M):
        out("WARN", "V7", "실무 가이드인데 복붙 프롬프트 섹션 — 스킬 지침('법·세무 글에 프롬프트는 신뢰도만 깎는다')과 충돌")
    c = counts(p); same_c = [q["name"] for q in rec if counts(q) == c]
    if same_c: rot("WARN", "V8", f"H2/표/이미지/{'금지항목' if PLATFORM=='naver' else 'FAQ'} 개수 {c} 가 직전 편과 동일: {', '.join(same_c)}")
    if not p["form"]: out("WARN", "V9", "프론트매터 form(글 유형) 없음 — " + "/".join(FORMS) + " 중 하나")
    elif p["form"] not in FORMS: out("WARN", "V9", f"form '{p['form']}' 은 6유형 이름이 아님 — " + "/".join(FORMS))
    else:
        dup = [q["name"] for q in prev if q["form"] == p["form"]]
        if dup: rot("FAIL", "V9", f"글 유형 '{p['form']}' 이 직전 편과 같음 (연속 금지): {', '.join(dup)}")
        win = sorted((q for q in posts if q["date"] and q["date"] < (p["date"] or "9999")), key=lambda q: q["date"])[-4:]
        n5 = sum(1 for q in win if q["form"] == p["form"])
        if n5 >= 2: rot("WARN", "V9b", f"직전 4편에 '{p['form']}' 이 이미 {n5}편 → 이 편까지 5편 안 3회 (2회 이하)")
    # V11 (2026-10-02): 제휴 글 상한 = 이 편까지 5편 안 1편 → 2026-10-11 6편 안 1편(AFF_GAP, V9b 창과 따로). 대가 표시는 제목 또는 첫 부분
    # (공정위 추천·보증 심사지침 — 글 하단 표기는 불충분), 시리즈의 "이해관계 없이" 고지는 쓰지 않는다
    if p["affiliate"]:
        if p["affiliate"] != AFFILIATE[PLATFORM]:
            out("WARN", "V11", f"affiliate '{p['affiliate']}' — {PLATFORM}은 '{AFFILIATE[PLATFORM]}'")
        if p["stock"]:
            print(f"  · V11 제휴 재고 원고 — {AFF_GAP + 1}편 안 1편은 배치(번호·예약일)할 때 검사한다")
        else:
            win = sorted((q for q in posts if q["date"] and q["date"] < (p["date"] or "9999")), key=lambda q: q["date"])[-AFF_GAP:]
            aff = [q["name"] for q in win if q["affiliate"]]
            if aff: out("FAIL", "V11", f"직전 {AFF_GAP}편에 제휴 글이 이미 있음 ({AFF_GAP + 1}편 안 1편): {', '.join(aff)}")
        if not re.search(DISCLOSE_RX, p["title"] + "\n" + p["body"][:800]):
            out("FAIL", "V11", "제휴 글인데 제목·본문 첫 부분에 대가 표시가 없음 (수수료·제휴·파트너스 문구)")
        if "이해관계 없이" in p["body"]:
            out("FAIL", "V11", "제휴 글에 '이해관계 없이' 고지가 남아 있음 — 삭제")
        if p["stock"] or (p["created"] or "") >= V12_FROM:
            heads = [p["title"]] + h2s(p["body"])
            if not any(re.search(AI_TERM_RX, h) for h in heads):
                out("FAIL", "V12", "제휴 글인데 제목·H2에 AI 말이 없음 — 'AI 활용 절차' 절로 블로그 주제와 잇는다 (SKILL STEP 0-2의 5)")
            else:   # 네이버 양식은 프롬프트를 인용블록(>)으로 쓴다 — AI 말이 든 H2 절 안에 인용블록이 있어야 한다
                secs = re.split(r"^## ", p["body"], flags=re.M)
                ai_secs = [s for s in secs[1:] if re.search(AI_TERM_RX, s.split("\n", 1)[0])]
                if not any(re.search(r"^>", s, re.M) for s in ai_secs):
                    out("WARN", "V12", "제휴 글의 AI 활용 절에 프롬프트 예시(인용블록)가 없음")
        # V13 (2026-10-07 Thomas): 직접 써 본 후기를 쓸 수 없으니 활용 장면과 실제 실행 결과로 채운다. 네이버 검색 실전편(06-04)이
        # '제조사 스펙시트를 그대로 옮기고 구매 링크만 강조하는 글'을 나쁜 예로 들었다 — 사양표 + 링크만 남는 꼴을 막는다
        if p["stock"] or (p["created"] or "") >= V13_FROM:
            secs = re.split(r"^## ", p["body"], flags=re.M)[1:]
            # 소제목 말이 아니라 사례 표시(①②③)로 센다 — '한 달 몇 분이면 AI녹음기가 필요한가요?'처럼 질문형 소제목 아래 사례도 장면이다(10-07)
            cases = max((len(re.findall(r"^[①-⑨]", s, re.M)) for s in secs), default=0)
            if cases < 3:
                out("WARN", "V13", f"제휴 글의 활용 장면 {cases}개 — 업종·상황별로 'AI로 하는 일 → 장비를 쓰는 장면 → 고를 조건'을 3개 이상 (SKILL STEP 0-2의 5)")
            if not re.search(r"돌려[보봤본]|넣어 ?(?:보[니았]|봤)|나온 결과|결과는 이랬|이렇게 나왔", p["body"]):
                out("WARN", "V13", "제휴 글에 AI 활용 절차를 실제로 돌려 본 결과가 없음 — 예시 입력과 실제 출력을 싣는다(모델명·날짜 괄호는 붙이지 않는다)")
    # V10 (2026-09-27): 티스토리 재작성본이 원본 네이버 원고와 겹치는지. V5는 같은 플랫폼끼리만 본다.
    # 실측: 47쌍 6-gram 평균 0.164, 같은 문장 101개(23쌍) — 구글은 비슷한 페이지 중 하나만 정규로 고르고,
    # 다음은 여러 호스트의 같은 문서를 검색에서 제한한다. 스킬 규칙은 "겹치는 문장 한 줄이라도 있으면 다시 쓴다".
    if PLATFORM == "tistory":
        src = source_of(p)
        if src:
            sb = load(src)["body"]
            gp, gs = grams(p["body"]), grams(sb)
            j = len(gp & gs) / max(1, len(gp | gs))
            same = sorted(sentences(p["body"], THRESH["src_sent"]) & sentences(sb, THRESH["src_sent"]), key=len, reverse=True)
            if same:
                out("FAIL", "V10", f"원본 네이버 원고와 같은 문장 {len(same)}개 — 사실은 두고 문장을 새로 쓴다: "
                    + " / ".join(f"'{x[:40]}…'" for x in same[:3]))
            if j >= THRESH["src_fail"]: out("FAIL", "V10", f"원본 네이버 원고와 6-gram 유사도 {j:.3f} (FAIL {THRESH['src_fail']}) — 문장·표 문구·사례를 보여 주는 방식을 새로 쓴다(사례 숫자·조건·경계는 그대로)")
            elif j >= THRESH["src_warn"]: out("WARN", "V10", f"원본 네이버 원고와 6-gram 유사도 {j:.3f} (WARN {THRESH['src_warn']}, 네이버 글끼리 평균 0.027)")
        elif re.search(r"^source:", p["fm"], re.M) and not re.search(r"^origin:[ \t]*tistory-only", p["fm"], re.M):   # 1-C 티스토리 전용 글은 원본이 없다(2026-10-03)
            out("WARN", "V10", "source: 의 원본 네이버 원고를 찾지 못해 중복 대조를 못 했다")
    if not fails and not warns: print("  OK")
    return fails

def report(posts):
    print(f"[{PLATFORM}] 코퍼스 {len(posts)}편")
    rc = collections.Counter()
    for p in posts:
        for h in ritual_hits(p): rc[h] += 1
    print("\n의례 문구 보유 편수:")
    for k in rituals(): print(f"  {rc[k]:2d}/{len(posts)}  {k}")
    print("\n제목 틀:", dict(collections.Counter(title_mold(p['title']) for p in posts)))
    print("마무리 틀:", dict(collections.Counter(closing_mold(p['body']) for p in posts)))
    if PLATFORM == "naver": print("끝 두 섹션 프롬프트→금지:", sum(1 for p in posts if signature(p)[-2:] == ("프롬프트", "금지")), "편")
    else: print("첫 섹션 '요약':", sum(1 for p in posts if signature(p)[:1] == ("요약",)), "편 / FAQ 5문항:", sum(1 for p in posts if faq_count(p['body']) == 5), "편")
    print("글 유형(form) 선언:", sum(1 for p in posts if p['form']), "편 / unique_asset 선언:", sum(1 for p in posts if p['unique']), "편")
    G = {p["name"]: grams(p["body"]) for p in posts}
    js = [len(G[a] & G[b]) / max(1, len(G[a] | G[b])) for a, b in itertools.combinations(G, 2)]
    if js: print(f"6-gram 유사도 평균 {statistics.mean(js):.3f} / 최대 {max(js):.3f}")
    print("\n의례 문구 개수별 편수:", dict(sorted(collections.Counter(len(ritual_hits(p)) for p in posts).items())))
    dated = sorted((q for q in posts if q["date"]), key=lambda q: q["date"])
    last = max((i for i, q in enumerate(dated) if q["affiliate"]), default=None)
    since = len(dated) - 1 - last if last is not None else len(dated)
    print(f"제휴 글: {sum(1 for q in posts if q['affiliate'] and not q['stock'])}편 / 마지막 제휴 글 이후 {since}편 → "
          + (f"다음 편은 제휴 차례 (목표: {AFF_TARGET}편째 안)" if since >= AFF_GAP else f"아직 아님 ({AFF_GAP - since}편 더 지나야)"))
    if since >= AFF_TARGET:
        print(f"  ⚠ 제휴 지연 — 마지막 제휴 글 이후 {since}편, 목표 {AFF_TARGET}편째를 넘김 (배치 가능 재고: blog-affiliate-place.py --list)")
    stock = sorted(q["name"] for q in posts if q["stock"])
    print(f"제휴 재고(번호·예약일 없음) {len(stock)}편" + (": " + ", ".join(stock) if stock else ""))
    print("\n최근 8편 (날짜순) 유형·제목틀·마무리:")
    for p in sorted((q for q in posts if q["date"]), key=lambda q: q["date"])[-8:]:
        print(f"  {p['date']}  {p['form'] or '-':<6} {title_mold(p['title']):<10} {closing_mold(p['body']):<8} {'제휴 ' if p['affiliate'] else ''}{p['name'][:34]}")


def configure(vault_root):
    """Point the corpus at a vault (generated: replaces the vault file's import-time BLOG_VAULT/__file__ lookup)."""
    global _VAULT, _CORPUS, CORPORA
    _VAULT = str(vault_root)
    _CORPUS = os.path.join(_VAULT, "content")
    CORPORA = {"naver": os.path.join(_CORPUS, "naver"), "tistory": os.path.join(_CORPUS, "tistory")}
